// Minimum confidence threshold for model predictions
export const MIN_CONFIDENCE = 0.15;

// Max suggestions to return
export const MAX_SUGGESTIONS = 6;

/**
 * Map a model prediction (class index + confidence) to Nepali food DB entries.
 * Returns food names only — caller looks up full FoodItem from NEPALI_FOODS.
 */
export function mapPredictionToFoods(
  classIndex: number,
  confidence: number
): { foodName: string; source: string; confidence: number }[] {
  if (confidence < MIN_CONFIDENCE) return [];

  const keywords = INDEX_TO_KEYWORDS[classIndex];
  if (!keywords) return [];

  const foods: { foodName: string; source: string; confidence: number }[] = [];
  const seen = new Set<string>();

  for (const kw of keywords) {
    const matches = KEYWORD_TO_FOODS[kw];
    if (!matches) continue;
    for (const foodName of matches) {
      if (seen.has(foodName)) continue;
      seen.add(foodName);
      foods.push({
        foodName,
        source: `model → "${kw}"`,
        confidence,
      });
    }
  }

  return foods.slice(0, MAX_SUGGESTIONS);
}
